window.JourneyUI = (() => {
  const data=window.COURT_JOURNEY;
  const selected=()=>data.stages.find(s=>s.id===new URLSearchParams(location.hash.split('?')[1]||'').get('stage'))||data.stages[1];
  const refs=()=>`<details class="journey-references"><summary>查看说明依据</summary><div>${data.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`).join('')}</div></details>`;
  const panel=s=>`<div class="journey-stage-story"><div class="journey-stage-image"><img src="assets/scenarios/${esc(s.photo)}.jpg" alt="${esc(s.caption)}" width="960" height="600"><div><span>STAGE / 0${data.stages.indexOf(s)+1}</span><p>${esc(s.caption)}</p></div></div><div class="journey-status"><span>我目前的进度</span><p>${esc(s.status)}</p></div><p class="journey-stage-note">${esc(s.note)}</p></div><div class="journey-stage-needs"><span class="eyebrow">02 / 对照你遇到的情况</span><h2>${esc(s.title)}</h2><p class="journey-intro">${esc(s.intro)}</p><div class="journey-needs">${s.needs.map((n,i)=>`<article class="journey-need"><span class="journey-need-number">0${i+1}</span><div><h3>${esc(n.question)}</h3><p>${esc(n.story)}</p><div class="journey-direction"><span>可了解</span><strong>${esc(data.services[n.service].guarantee)}</strong></div><p class="journey-direction-copy">${esc(n.direction)}</p><a class="journey-need-link" href="#/scenarios/${esc(n.service)}?stage=${esc(s.id)}">查看办理流程与材料 ${icon('arrow')}</a></div></article>`).join('')}</div></div>`;
  function html(){const s=selected();return `<div class="journey-page"><section class="container journey-hero"><div class="editorial-eyebrow"><span>保函介绍</span><span>YOUR CASE. YOUR NEXT STEP.</span></div><div class="journey-hero-grid"><h1>你遇到的情况，<br><span>需要哪种保函？</span></h1><div><p>担心对方转走钱，还是自己的账户被冻结？<br>先选案件阶段，再对照具体情况，<br>查看相关保函和材料清单。</p><span class="journey-reading-path">选阶段 / 看情况 / 准备办理</span></div></div></section><section class="container journey-selector" id="journey-selector" aria-labelledby="journey-selector-title"><div class="journey-section-label"><h2 id="journey-selector-title">01 / 选择你所处的阶段</h2><span>普通民事案件的常见进程</span></div><div class="journey-tabs" role="tablist" aria-label="案件所处阶段">${data.stages.map((x,i)=>`<button type="button" role="tab" id="stage-tab-${x.id}" aria-controls="journey-panel" aria-selected="${x.id===s.id}" tabindex="${x.id===s.id?'0':'-1'}" data-journey-stage="${x.id}"><span>0${i+1}</span><strong>${esc(x.name)}</strong><small>${i===3?'发生上诉时进入':i===4?'以生效文书为基础':i===0?'尚未起诉':i===1?'起诉与受理':'举证 / 开庭 / 裁判'}</small></button>`).join('')}</div><p class="journey-process-note">一审包含审理与裁判；未上诉并生效的案件可直接进入执行申请阶段。具体进程以案件适用程序为准。</p></section><section class="container journey-panel" id="journey-panel" role="tabpanel" aria-labelledby="stage-tab-${s.id}" tabindex="0">${panel(s)}</section><section class="container journey-reverse"><span class="journey-reverse-icon">${icon('unlock')}</span><div><span class="eyebrow">如果你是被保全的一方</span><h2>我的账户或财产，已经被保全。</h2><p>不确定案件在哪个阶段？可先了解解除保全担保与措施变更的准备事项。</p></div>${link('/scenarios/release-preservation?stage='+s.id,'查看解除保全需求 '+icon('arrow'),'button outline journey-reverse-link')}</section><section class="container journey-bottom"><p>以上用于识别常见需求，不是每个阶段都需要保函。具体适用条件、担保形式及材料，以法院和出函机构要求为准。</p>${refs()}</section></div>`}
  function bind(){const tabs=[...document.querySelectorAll('[data-journey-stage]')];if(!tabs.length)return;const choose=button=>{const s=data.stages.find(s=>s.id===button.dataset.journeyStage);if(!s)return;tabs.forEach(b=>{const active=b===button;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1});const host=document.querySelector('#journey-panel');host.innerHTML=panel(s);host.setAttribute('aria-labelledby',button.id);host.classList.remove('journey-panel-enter');void host.offsetWidth;host.classList.add('journey-panel-enter');history.replaceState(null,'','#/scenarios?stage='+s.id);document.querySelector('.journey-reverse-link').href='#/scenarios/release-preservation?stage='+s.id};tabs.forEach((b,i)=>{b.onclick=()=>choose(b);b.onkeydown=e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;else if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();tabs[next].focus();choose(tabs[next])}}})}
  function detail(s){const d=data.services[s.id],stage=selected();return `<div class="journey-detail"><section class="container journey-detail-heading"><a class="back-link" href="#/scenarios?stage=${esc(stage.id)}">← 返回${esc(stage.name)}场景</a><div class="eyebrow">03 / 了解保函与办理准备</div><h1>${esc(d.guarantee)}</h1><p>${esc(d.when)}</p></section><section class="container journey-detail-layout"><article><figure class="scenario-detail-photo"><img src="${esc(s.image)}" alt="${esc(s.imageAlt)}" width="960" height="600"><figcaption>${esc(s.imageCaption)}<span>配图仅作示意</span></figcaption></figure><h2>保函知识介绍</h2><p>${esc(s.detail)}</p><h2>谁需要办理</h2><p>${esc(d.role)}。适用情形：${esc(d.when)}。</p><h2>四步办理流程</h2><ol class="journey-materials">${['提交案件材料','自主选择机构','智能核保','在线缴费出函'].map((step,i)=>`<li><span>0${i+1}</span>${step}</li>`).join('')}</ol><h2>办理所需材料</h2><p class="journey-material-note">可先按下面的清单整理，实际提交时再核对法院和出函机构的要求。</p><ol class="journey-materials">${d.materials.map((m,i)=>`<li><span>0${i+1}</span>${esc(m)}</li>`).join('')}</ol><h2>法院认可依据</h2><p>${esc(d.condition)}</p><a class="text-link" href="${esc(d.legalUrl || data.sources[0].url)}" target="_blank" rel="noopener noreferrer">${esc(d.legalTitle)} ↗</a></article><aside class="journey-next"><span class="eyebrow">YOUR NEXT STEP</span><h2>材料整理好后，<br>还要问清什么？</h2><p>先确认受理法院、担保金额、担保期限及认可的出函主体，再向机构核实是否承接该项业务。</p>${link('/institutions','查看机构信息 '+icon('arrow'),'button primary')}${link('/help','查看常见问题 '+icon('arrow'),'text-link')}<div class="journey-next-note">保函是可能采用的担保形式之一。出函与法院采取措施属于不同环节。</div></aside></section></div>`}
  return {html,bind,detail};
})();
